<?php
function adminPage(string $path): void {
 header('Cache-Control: no-store');
 if($path==='/admin/login') {
  $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf(); if(limited('login',10))$error='Please wait 15 minutes before trying again.'; else { $u=query('SELECT * FROM admins WHERE email=?',[trim((string)($_POST['email']??''))])->fetch(); if($u && password_verify((string)($_POST['password']??''),$u['password_hash'])) {session_regenerate_id(true);$_SESSION['admin']=$u['id'];$_SESSION['admin_seen']=time();redirect('/admin');} $error='Please check your email and password.'; }}
  layout('Owner login',function()use($error){echo '<form method="post" class="admin-login"><p class="eyebrow">WHITE GOLD FARM</p><h1>Welcome back.</h1>';token();field('email','Email','','email');field('password','Password','','password');echo '<p role="alert">'.e($error).'</p><button class="button full">Sign in</button></form>';},true);return;
 }
 admin(); $error='';
 if($_SERVER['REQUEST_METHOD']==='POST') {
  csrf(); try {
   $action=$_POST['action']??'';
   if($action==='logout'){$_SESSION=[];session_destroy();redirect('/admin/login');}
   if($action==='category-add'){ $name=trim((string)($_POST['name']??''));if(strlen($name)<2||strlen($name)>60)throw new DomainException('Category must contain 2–60 characters.');query('INSERT INTO categories(name) VALUES(?)',[$name]); }
   elseif($action==='category-delete')query('DELETE FROM categories WHERE name=?',[$_POST['name']??'']);
   elseif($action==='delete')query('DELETE FROM products WHERE id=?',[$_POST['id']??'']);
   elseif($action==='move') {
    db()->beginTransaction();$all=query('SELECT id FROM products ORDER BY sort_order,created_at,id FOR UPDATE')->fetchAll(PDO::FETCH_COLUMN);$i=array_search($_POST['id']??'',$all,true);$j=$i+(($_POST['direction']??'')==='up'?-1:1);if($i!==false&&isset($all[$j])){[$all[$i],$all[$j]]=[$all[$j],$all[$i]];foreach($all as $n=>$id)query('UPDATE products SET sort_order=? WHERE id=?',[$n+1,$id]);}db()->commit();
   } elseif($action==='inline') {
    $price=filter_var($_POST['price']??'',FILTER_VALIDATE_FLOAT);$compare=($_POST['compare_price']??'')===''?null:filter_var($_POST['compare_price'],FILTER_VALIDATE_FLOAT);
    if($price===false||$price<=0||$price>1000000||($compare!==null&&($compare===false||$compare<=$price||$compare>1000000)))throw new DomainException('Check price and compare price.');
    query('UPDATE products SET price=?,compare_price=?,in_stock=? WHERE id=?',[$price,$compare,isset($_POST['in_stock'])?1:0,$_POST['id']??'']);
   } elseif($action==='save') {
    $id=(string)($_POST['id']??'');$old=$id?query('SELECT * FROM products WHERE id=?',[$id])->fetch():false;
    $name=trim((string)($_POST['name']??''));$cat=(string)($_POST['category']??'');$desc=trim((string)($_POST['description']??''));$unit=trim((string)($_POST['unit']??''));$price=filter_var($_POST['price']??'',FILTER_VALIDATE_FLOAT);$compare=($_POST['compare_price']??'')===''?null:filter_var($_POST['compare_price'],FILTER_VALIDATE_FLOAT);
    if(strlen($name)<2||strlen($name)>100||strlen($desc)<10||strlen($desc)>2000||strlen($unit)<1||strlen($unit)>50||$price===false||$price<=0||$price>1000000||($compare!==null&&($compare===false||$compare<=$price||$compare>1000000))||!in_array($cat,categories(),true))throw new DomainException('Check the product fields. Compare price must exceed price.');
    $image=$old['image']??'/images/milk.png';$file=$_FILES['image']??null;
    if($file&&$file['error']!==UPLOAD_ERR_NO_FILE){if($file['error']!==UPLOAD_ERR_OK||$file['size']>5242880)throw new DomainException('Choose an image below 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext||!getimagesize($file['tmp_name']))throw new DomainException('Choose a valid JPG, PNG or WebP.');$key=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($file['tmp_name'],dirname(__DIR__).'/storage/uploads/'.$key))throw new DomainException('Image upload failed.');$image='/media/'.$key;}
    $values=[$name,$cat,$desc,$image,$price,$compare,$unit,isset($_POST['in_stock'])?1:0];
    if($old)query('UPDATE products SET name=?,category=?,description=?,image=?,price=?,compare_price=?,unit=?,in_stock=? WHERE id=?',[...$values,$id]);else query('INSERT INTO products(name,category,description,image,price,compare_price,unit,in_stock,id) VALUES(?,?,?,?,?,?,?,?,?)',[...$values,uuid()]);
   } else throw new DomainException('Unknown action.');
   $_SESSION['flash']='Changes saved.';redirect('/admin');
  } catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=$e instanceof DomainException?$e->getMessage():'Could not save. Category names must be unique; move or delete products before deleting their category.';}
 }
 $edit=isset($_GET['edit'])?query('SELECT * FROM products WHERE id=?',[$_GET['edit']])->fetch():false;
 layout('Owner dashboard',function()use($error,$edit){
  echo '<section class="admin-shell"><div class="admin-top"><div><p class="eyebrow">OWNER DASHBOARD</p><h1>Your shop, at a glance.</h1></div>';actionForm('logout','Sign out');echo '</div><p role="status">'.e($_SESSION['flash']??'').'</p>';unset($_SESSION['flash']);echo '<p class="error-text" role="alert">'.e($error).'</p><nav class="category-page-links"><a href="#products">Products</a><a href="#orders">Orders</a></nav><section class="admin-category-panel"><h2>Product categories</h2><div class="category-chips">';foreach(categories() as $c){echo '<span>'.e($c);actionForm('category-delete','Delete',['name'=>$c],true);echo '</span>';}echo '</div><form method="post">';token();echo '<input type="hidden" name="action" value="category-add">';field('name','New category');echo '<button class="button">Add category</button></form></section><h2 id="products">Products</h2><div class="table-wrap"><table class="admin-table"><thead><tr><th>Order</th><th>Product</th><th>Price</th><th>Stock</th><th>Actions</th></tr></thead><tbody>';
  $ps=products();foreach($ps as $i=>$p){echo '<tr><td>';if($i>0)actionForm('move','↑',['id'=>$p['id'],'direction'=>'up']);if($i<count($ps)-1)actionForm('move','↓',['id'=>$p['id'],'direction'=>'down']);echo '</td><td>'.e($p['name']).'<br><small>'.e($p['category']).'</small></td><td>'.'<form method="post"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="action" value="inline"><input type="hidden" name="id" value="'.e($p['id']).'"><input class="admin-input" aria-label="Price for '.e($p['name']).'" name="price" type="number" min="0.01" step="0.01" value="'.e($p['price']).'" required><input class="admin-input" aria-label="Compare price for '.e($p['name']).'" name="compare_price" type="number" min="0.01" step="0.01" value="'.e($p['compare_price']??'').'"><label><input name="in_stock" type="checkbox" '.($p['in_stock']?'checked':'').'> In stock</label><button class="small-button">Save</button></form>'.'</td><td>'.($p['in_stock']?'In stock':'Out of stock').'</td><td><a class="small-button" href="/admin?edit='.e($p['id']).'#edit">Edit</a>';actionForm('delete','Delete',['id'=>$p['id']],true);echo '</td></tr>';}
  echo '</tbody></table></div><form id="edit" class="admin-edit" method="post" enctype="multipart/form-data"><h2>'.($edit?'Edit product':'Add a product').'</h2>';token();echo '<input type="hidden" name="action" value="save"><input type="hidden" name="id" value="'.e($edit['id']??'').'"><div class="form-grid">';field('name','Product name',$edit['name']??'');echo '<label class="field">Category<select name="category" required>';foreach(categories() as $c)echo '<option '.(($edit['category']??'')===$c?'selected':'').'>'.e($c).'</option>';echo '</select></label>';field('price','Price (PKR)',(string)($edit['price']??''));echo '<label class="field">Compare price (optional)<input name="compare_price" inputmode="decimal" value="'.e($edit['compare_price']??'').'"></label>';field('unit','Unit',$edit['unit']??'');echo '<label class="field">Photo (up to 5 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label></div><label class="field">Description<textarea name="description" required>'.e($edit['description']??'').'</textarea></label><label><input type="checkbox" name="in_stock" '.((!$edit||$edit['in_stock'])?'checked':'').'> In stock</label><p><button class="button">Save product</button> <a href="/admin#edit">New product</a></p></form><h2 id="orders">Latest orders</h2>';
  $page=max(1,(int)($_GET['page']??1));$offset=($page-1)*25;$orders=query('SELECT * FROM orders ORDER BY created_at DESC LIMIT 25 OFFSET '.$offset)->fetchAll();foreach($orders as $o){echo '<details class="admin-order"><summary>'.e($o['order_reference']).' · '.e($o['full_name']).' · '.money($o['total']).'</summary><p>'.e($o['phone']).'<br>'.e($o['address'].', '.$o['city']).'<br>'.e($o['created_at']).' UTC<br>Email: '.e($o['email_status']).'</p><ul>';foreach(query('SELECT * FROM order_items WHERE order_id=?',[$o['id']])->fetchAll() as $i)echo '<li>'.e($i['product_name'].' · '.$i['unit'].' × '.$i['quantity']).' — '.money($i['line_total']).'</li>';echo '</ul><p>'.nl2br(e($o['notes'])).'</p></details>';}if(count($orders)===25)echo '<a href="/admin?page='.($page+1).'#orders">Older orders →</a>';echo '</section>';
 },true);
}
function actionForm(string $action,string $label,array $fields=[],bool $confirm=false): void {echo '<form class="inline-form" method="post" '.($confirm?'data-confirm="Are you sure? Existing order records will be preserved."':'').'>';token();echo '<input type="hidden" name="action" value="'.e($action).'">';foreach($fields as $k=>$v)echo '<input type="hidden" name="'.e($k).'" value="'.e($v).'">';echo '<button class="small-button">'.e($label).'</button></form>';}
